CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','manager','viewer')), revision INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS preferences(owner TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS device_groups(device TEXT NOT NULL REFERENCES devices(id),grp TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE,PRIMARY KEY(device,grp));
CREATE TABLE IF NOT EXISTS notification_channels(id TEXT PRIMARY KEY,name TEXT NOT NULL,recipients TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS notification_rules(id TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_queue(id TEXT PRIMARY KEY,event TEXT REFERENCES events(id) ON DELETE CASCADE,rule TEXT,channel TEXT NOT NULL REFERENCES notification_channels(id) ON DELETE CASCADE,phase TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_try INTEGER NOT NULL,created INTEGER NOT NULL,sent INTEGER,error TEXT,UNIQUE(event,rule,channel,phase));
CREATE INDEX IF NOT EXISTS notification_due ON notification_queue(status,next_try);
CREATE INDEX IF NOT EXISTS notification_created ON notification_queue(created DESC);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,at INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL);
